#!/usr/bin/env bash
#
# Deskboard launcher: resolve the checkout (even through a symlink), load the
# private typelib environment, then run the application.
#
#   scripts/run.sh                 # normal start
#   scripts/run.sh --demo          # offline sample data
#   scripts/run.sh --doctor        # environment / API diagnostics
#
# ~/.local/bin/deskboard is usually a small wrapper generated by install.sh, but
# this script can itself be symlinked from ~/.local/bin.
set -euo pipefail

resolve_script_dir() {
  local src="${BASH_SOURCE[0]}" dir
  while [ -L "$src" ]; do
    dir="$(cd -P -- "$(dirname -- "$src")" >/dev/null 2>&1 && pwd)"
    src="$(readlink -- "$src")"
    case "$src" in
      /*) ;;
      *) src="$dir/$src" ;;
    esac
  done
  cd -P -- "$(dirname -- "$src")" >/dev/null 2>&1 && pwd
}

SCRIPT_DIR="$(resolve_script_dir)"
ROOT="$(cd -P -- "$SCRIPT_DIR/.." >/dev/null 2>&1 && pwd)"

if [ ! -f "$ROOT/deskboard/__main__.py" ]; then
  printf 'Deskboard: cannot find the application under %s\n' "$ROOT" >&2
  printf 'Re-run the installer from a fresh checkout: scripts/install.sh\n' >&2
  exit 1
fi
if [ ! -f "$ROOT/scripts/env.sh" ]; then
  printf 'Deskboard: missing %s/scripts/env.sh\n' "$ROOT" >&2
  exit 1
fi

# env.sh sets PYTHONPATH from $PWD, so run from the application root.
cd -- "$ROOT"

# shellcheck disable=SC1091
. "$ROOT/scripts/env.sh"

PYTHON_BIN="${DESKBOARD_PYTHON:-python3}"
if ! command -v "$PYTHON_BIN" >/dev/null 2>&1; then
  printf 'Deskboard: %s was not found. Install Python 3 and python3-gi.\n' "$PYTHON_BIN" >&2
  exit 1
fi

# The CLI-only commands must keep working when GTK is broken, because
# `--doctor` is exactly how users diagnose that. For everything else, fail with
# a useful hint instead of a stack trace.
preflight=1
for argument in "$@"; do
  case "$argument" in
    -h|--help|--version|--doctor|--import-cookies)
      preflight=0
      ;;
  esac
done

if [ "$preflight" -eq 1 ]; then
  if ! "$PYTHON_BIN" -c 'import gi; gi.require_version("Gtk", "4.0"); gi.require_version("Adw", "1")' >/dev/null 2>&1; then
    printf '\nDeskboard: GTK 4 / libadwaita typelibs are not available.\n\n' >&2
    printf '  Install them into your user account (no root needed):\n' >&2
    printf '      %s/scripts/bootstrap-gir.sh\n\n' "$ROOT" >&2
    printf '  Then retry, or run the installer to get a permanent launcher:\n' >&2
    printf '      %s/scripts/install.sh\n\n' "$ROOT" >&2
    printf '  Diagnose the environment with:  %s/scripts/run.sh --doctor\n\n' "$ROOT" >&2
    exit 1
  fi
fi

exec "$PYTHON_BIN" -m deskboard "$@"
